{
  "components": [
    {
      "type": "claim",
      "quote": "Das Forschungsprogramm Bioenergie begleitet innovative und für die Schweiz relevante Themen in der Energiebereitstellung aus Biomasse.",
      "gist": "The Bioenergy research program focuses on innovative and relevant topics for Switzerland in energy supply from biomass."
    },
    {
      "type": "obligation",
      "quote": "Das Programm koordiniert die anwendungsorientierte Forschung auf nationaler Ebene, nutzt Synergien und sorgt für die internationale Vernetzung.",
      "gist": "The program coordinates application-oriented research at the national level, utilizes synergies, and ensures international networking."
    },
    {
      "type": "claim",
      "quote": "Zentral ist dabei die Frage, welche Biomassefraktionen zukünftig mit welchen Technologien zu welchen Produkten umgesetzt werden, um für das Schweizer Energiesystem einen substanziellen Beitrag zu leisten und gleichzeitig einen hohen Wirkungsgrad zu erzielen.",
      "gist": "Central is the question of which biomass fractions will be converted into which products using which technologies to make a substantial contribution to the Swiss energy system while achieving high efficiency."
    }
  ]
}
